import React, { useState } from 'react';
import { Sun, Moon, Home, Info, Settings, User, LogIn, UserPlus, Globe } from 'lucide-react';

const Header = ({ darkMode, toggleDarkMode }) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [langOpen, setLangOpen] = useState(false);
  const [lang, setLang] = useState("fr");

  // Traductions
  const translations = {
    fr: {
      home: "Accueil",
      about: "À propos",
      profile: "Profil",
      settings: "Paramètres",
      login: "Connexion",
      register: "Créer un compte",
    },
    en: {
      home: "Home",
      about: "About",
      profile: "Profile",
      settings: "Settings",
      login: "Login",
      register: "Register",
    },
    mg: {
      home: "Fandraisana",
      about: "Mombamomba",
      profile: "Tantara",
      settings: "Fikirana",
      login: "Hiditra",
      register: "Hisoratra",
    }
  };

  const t = translations[lang];

  // Menu navigation
  const navItems = [
    { icon: <Home size={20} />, label: t.home, href: "#" },
    { icon: <Info size={20} />, label: t.about, href: "#" },
    { icon: <User size={20} />, label: t.profile, href: "#" },
    { icon: <Settings size={20} />, label: t.settings, href: "#" },
  ];

  return (
    <header className="sticky top-0 z-50 w-full border-b border-neutral-200 dark:border-neutral-800 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-md">

      <div className="container mx-auto px-4 py-3 flex items-center justify-between">

        {/* LOGO */}
        <div className="flex items-center space-x-2 cursor-pointer">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center">
            <span className="text-white font-bold">R</span>
          </div>
          <h1 className="text-xl font-bold dark:text-white">ReactUI</h1>
        </div>

        {/* NAV Desktop */}
        <nav className="hidden md:flex items-center space-x-4">
          {navItems.map((item) => (
            <a
              key={item.label}
              href={item.href}
              className="flex items-center gap-2 px-3 py-2 rounded-lg cursor-pointer
                         text-neutral-700 dark:text-neutral-300
                         hover:bg-neutral-100 dark:hover:bg-neutral-800 transition"
            >
              {item.icon}
              <span>{item.label}</span>
            </a>
          ))}
        </nav>

        {/* ACTIONS */}
        <div className="flex items-center space-x-3">

          {/* LANG BUTTON */}
          <div className="relative">
            <button
              onClick={() => setLangOpen(!langOpen)}
              className="p-2 rounded-lg cursor-pointer hover:bg-neutral-100 dark:hover:bg-neutral-800"
            >
              <Globe size={20} />
            </button>

            {langOpen && (
              <div className="absolute right-0 mt-2 w-40 bg-white dark:bg-neutral-800 border dark:border-neutral-700 rounded-lg shadow-lg p-2">
                <button
                  onClick={() => { setLang("fr"); setLangOpen(false); }}
                  className="block w-full text-left px-3 py-2 rounded hover:bg-neutral-100 dark:hover:bg-neutral-700"
                >🇫🇷 Français</button>

                <button
                  onClick={() => { setLang("en"); setLangOpen(false); }}
                  className="block w-full text-left px-3 py-2 rounded hover:bg-neutral-100 dark:hover:bg-neutral-700"
                >🇬🇧 English</button>

                <button
                  onClick={() => { setLang("mg"); setLangOpen(false); }}
                  className="block w-full text-left px-3 py-2 rounded hover:bg-neutral-100 dark:hover:bg-neutral-700"
                >🇲🇬 Malagasy</button>
              </div>
            )}
          </div>

          {/* LOGIN */}
          <a href="#" className="hidden md:flex p-2 rounded-lg bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200 dark:hover:bg-neutral-700 cursor-pointer transition">
            <LogIn size={18} />
          </a>

          {/* REGISTER */}
          <a href="#" className="hidden md:flex p-2 rounded-lg bg-primary-600 text-white hover:bg-primary-700 cursor-pointer transition">
            <UserPlus size={18} />
          </a>

          {/* DARK MODE */}
          <button
            onClick={toggleDarkMode}
            className="p-2 rounded-lg cursor-pointer hover:bg-neutral-100 dark:hover:bg-neutral-800"
          >
            {darkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>

          {/* MOBILE TOGGLE */}
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="md:hidden p-2 rounded-lg cursor-pointer hover:bg-neutral-100 dark:hover:bg-neutral-800"
          >
            <div className="space-y-1">
              <div className={`w-6 h-0.5 bg-current transition ${mobileMenuOpen ? "rotate-45 translate-y-2" : ""}`} />
              <div className={`w-6 h-0.5 bg-current transition ${mobileMenuOpen ? "opacity-0" : "opacity-100"}`} />
              <div className={`w-6 h-0.5 bg-current transition ${mobileMenuOpen ? "-rotate-45 -translate-y-2" : ""}`} />
            </div>
          </button>

        </div>
      </div>

      {/* MOBILE MENU */}
      {mobileMenuOpen && (
        <div className="md:hidden px-4 py-3 border-t dark:border-neutral-800 space-y-2">
          {navItems.map((item) => (
            <a key={item.label} href={item.href}
              className="flex items-center gap-3 px-4 py-3 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 cursor-pointer">
              {item.icon}
              <span>{item.label}</span>
            </a>
          ))}

          <a className="flex items-center gap-3 px-4 py-3 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 cursor-pointer">
            <LogIn size={18} /> <span>{t.login}</span>
          </a>

          <a className="flex items-center gap-3 px-4 py-3 rounded-lg bg-primary-600 text-white cursor-pointer">
            <UserPlus size={18} /> <span>{t.register}</span>
          </a>
        </div>
      )}

    </header>
  );
};

export default Header;
